
const WORDS=[{"id": 0, "w": "培养", "p": "péiyǎng", "t": "动词", "m": "bồi dưỡng, đào tạo", "coll": "培养人才、培养习惯", "s": "这家公司十分重视培养年轻员工的专业能力。"}, {"id": 1, "w": "对手", "p": "duìshǒu", "t": "名词", "m": "đối thủ, địch thủ", "coll": "竞争对手、尊重对手", "s": "在激烈的市场竞争中，我们也应该尊重自己的对手。"}, {"id": 2, "w": "公寓", "p": "gōngyù", "t": "名词", "m": "khu nhà ở", "coll": "租公寓、一套公寓", "s": "为了方便上班，她在公司附近租了一套公寓。"}, {"id": 3, "w": "文具", "p": "wénjù", "t": "名词", "m": "đồ dùng văn phòng", "coll": "购买文具、文具店", "s": "开学以前，家长们带着孩子去商店购买文具。"}, {"id": 4, "w": "电池", "p": "diànchí", "t": "名词", "m": "pin", "coll": "更换电池、电池没电", "s": "遥控器不能用了，可能需要更换新的电池。"}, {"id": 5, "w": "日用品", "p": "rìyòngpǐn", "t": "名词", "m": "vật dụng hằng ngày", "coll": "购买日用品、生活日用品", "s": "这家小商店主要出售附近居民需要的日用品。"}, {"id": 6, "w": "利润", "p": "lìrùn", "t": "名词", "m": "lợi nhuận, lãi", "coll": "获得利润、提高利润", "s": "通过降低成本，这家工厂获得了更多的利润。"}, {"id": 7, "w": "诚信", "p": "chéngxìn", "t": "形容词", "m": "trung thực", "coll": "讲究诚信、诚信经营", "s": "无论生意大小，经营者都应该坚持诚信经营。"}, {"id": 8, "w": "媒体", "p": "méitǐ", "t": "名词", "m": "phương tiện truyền thông", "coll": "新闻媒体、媒体报道", "s": "这次公益活动吸引了多家媒体的关注。"}, {"id": 9, "w": "对象", "p": "duìxiàng", "t": "名词", "m": "đối tượng, mục tiêu", "coll": "服务对象、研究对象", "s": "在开发新产品之前，公司首先要确定主要的服务对象。"}, {"id": 10, "w": "营业", "p": "yíngyè", "t": "动词", "m": "kinh doanh, buôn bán", "coll": "开始营业、营业时间", "s": "这家商店每天早上八点开始营业。"}, {"id": 11, "w": "额", "p": "é", "t": "名词", "m": "số, ngạch, mức", "coll": "营业额、销售额", "s": "由于顾客增加，商店这个月的营业额明显提高了。"}, {"id": 12, "w": "不如", "p": "bùrú", "t": "动词", "m": "không bằng, thua kém hơn", "coll": "不如别人、还不如", "s": "与其一直抱怨困难，不如先行动起来，想办法解决问题。"}, {"id": 13, "w": "干脆", "p": "gāncuì", "t": "副词", "m": "dứt khoát, cứ", "coll": "干脆放弃、干脆住下", "s": "既然末班车已经开走了，我们干脆在附近住一晚吧。"}, {"id": 14, "w": "挤", "p": "jǐ", "t": "动词", "m": "ép, bóp, chen lấn", "coll": "挤进人群、挤公交车", "s": "早晨上班的时候，他好不容易才挤上了公交车。"}, {"id": 15, "w": "垮", "p": "kuǎ", "t": "动词", "m": "sập, sụp đổ", "coll": "累垮身体、房屋倒垮", "s": "长期不注意休息，很容易把身体累垮。"}, {"id": 16, "w": "垄断", "p": "lǒngduàn", "t": "动词", "m": "giữ độc quyền", "coll": "垄断市场、垄断经营", "s": "如果一家公司垄断了市场，消费者可能就会失去选择的机会。"}, {"id": 17, "w": "倒闭", "p": "dǎobì", "t": "动词", "m": "đóng cửa hẳn, sập tiệm", "coll": "公司倒闭、面临倒闭", "s": "由于经营不善，那家开了多年的商店最终倒闭了。"}, {"id": 18, "w": "热心", "p": "rèxīn", "t": "形容词", "m": "nhiệt tình, sốt sắng", "coll": "热心帮助、热心公益", "s": "附近的居民都很热心，经常主动帮助遇到困难的人。"}, {"id": 19, "w": "资金", "p": "zījīn", "t": "名词", "m": "tiền vốn", "coll": "缺乏资金、筹集资金", "s": "为了扩大生产，公司正在积极筹集资金。"}, {"id": 20, "w": "傻", "p": "shǎ", "t": "形容词", "m": "dại dột, đần độn", "coll": "别做傻事、显得很傻", "s": "明知道有风险却不做准备，这样的做法实在有点傻。"}, {"id": 21, "w": "倒霉", "p": "dǎoméi", "t": "形容词", "m": "xui xẻo, bất hạnh", "coll": "真倒霉、倒霉的事", "s": "今天真倒霉，刚出门就遇到大雨，连伞也没带。"}, {"id": 22, "w": "生态", "p": "shēngtài", "t": "名词", "m": "sinh thái", "coll": "生态环境、生态平衡", "s": "发展经济的同时，我们也必须保护当地的生态环境。"}, {"id": 23, "w": "商业", "p": "shāngyè", "t": "名词", "m": "thương mại, thương nghiệp", "coll": "商业活动、商业中心", "s": "经过多年的发展，这里已经成为繁华的商业中心。"}, {"id": 24, "w": "领域", "p": "lǐngyù", "t": "名词", "m": "lĩnh vực, phạm vi", "coll": "专业领域、研究领域", "s": "这位专家在环境保护领域积累了丰富的经验。"}, {"id": 25, "w": "适当", "p": "shìdàng", "t": "形容词", "m": "thích hợp, thỏa đáng", "coll": "适当调整、适当休息", "s": "连续工作一段时间以后，我们应该进行适当的休息。"}, {"id": 26, "w": "促使", "p": "cùshǐ", "t": "动词", "m": "thúc đẩy, thúc giục", "coll": "促使改变、促使进步", "s": "激烈的竞争促使企业不断改进产品质量。"}, {"id": 27, "w": "生长", "p": "shēngzhǎng", "t": "动词", "m": "sinh trưởng", "coll": "植物生长、生长环境", "s": "充足的阳光和水分有利于植物的生长。"}, {"id": 28, "w": "妨碍", "p": "fáng'ài", "t": "动词", "m": "gây trở ngại, cản trở", "coll": "妨碍交通、妨碍工作", "s": "请把自行车放到规定的位置，不要妨碍别人通行。"}, {"id": 29, "w": "促进", "p": "cùjìn", "t": "动词", "m": "đẩy mạnh, xúc tiến", "coll": "促进发展、促进交流", "s": "这次展览有助于促进两国企业之间的交流。"}, {"id": 30, "w": "利益", "p": "lìyì", "t": "名词", "m": "lợi ích", "coll": "共同利益、保护利益", "s": "制订合作计划时，双方都应该考虑彼此的利益。"}, {"id": 31, "w": "合理", "p": "hélǐ", "t": "形容词", "m": "hợp lý", "coll": "合理安排、合理价格", "s": "商店不仅提供优质服务，还坚持以合理的价格销售商品。"}, {"id": 32, "w": "万一", "p": "wànyī", "t": "连词", "m": "ngộ nhỡ", "coll": "万一下雨、以防万一", "s": "出门时最好带把伞，万一下雨，就不用临时找地方躲雨了。"}, {"id": 33, "w": "维持", "p": "wéichí", "t": "动词", "m": "duy trì, giữ lại", "coll": "维持生活、维持秩序", "s": "刚开店的时候，他的收入只能勉强维持生活。"}, {"id": 34, "w": "饱和", "p": "bǎohé", "t": "形容词", "m": "bão hòa", "coll": "市场饱和、达到饱和", "s": "随着同类产品不断增加，这个市场已经接近饱和。"}, {"id": 35, "w": "不见得", "p": "bùjiàndé", "t": "副词", "m": "chưa chắc, không nhất thiết", "coll": "不见得正确、不见得有效", "s": "价格高的商品不见得就一定适合自己。"}];
